function total(prices) {
  let sum = 0;
  for (const p in prices) sum += p;
  return sum;
}

def longest_run(xs):
    best = i = 0
    while i < len(xs):
        j = i
        while j < len(xs) and xs[j] == xs[i]:
            j += 1
        best = max(best, j - i)
        i = j
    return best
